Item.method_code:
	return UpdateWidgetTemplateProperties();
}

static string widgetTemplatePropTypeName = "Dashboard Widget Template Prop";
static string tableName = widgetTemplatePropTypeName.Replace(' ', '_');

const string favoriteSearchPropertyName = "favorite_search_id";
const string searchCriteriaPropertyName = "search_criteria";
const string layoutPropertyName = "favorite_layout";

Item UpdateWidgetTemplateProperties()
{
	Item favoriteSearchItem = GetWidgetTemplateProperty(favoriteSearchPropertyName);
	Item searchCriteriaItem = GetWidgetTemplateProperty(searchCriteriaPropertyName);
	Item layoutItem = GetWidgetTemplateProperty(layoutPropertyName);
	if (favoriteSearchItem == null)
	{
		if (IsFavoriteSearchItemBeingDeleted())
		{
			DeleteWidgetTemplatePropertyItem(searchCriteriaItem, searchCriteriaPropertyName);
			DeleteWidgetTemplatePropertyItem(layoutItem, layoutPropertyName);
		}

		return this;
	}

	string favoriteSearchId = favoriteSearchItem.getProperty("prop_predefined");
	Newtonsoft.Json.Linq.JToken additionalData;
	if (string.IsNullOrEmpty(favoriteSearchId) || (additionalData = GetFavoriteAdditionalData(favoriteSearchId)) == null)
	{
		DeleteWidgetTemplatePropertyItem(searchCriteriaItem, searchCriteriaPropertyName);
		DeleteWidgetTemplatePropertyItem(layoutItem, layoutPropertyName);

		return this;
	}

	SetFavoriteDataToWidgetTemplateProperty(searchCriteriaItem, searchCriteriaPropertyName, additionalData["criteria"]?.ToString());
	SetFavoriteDataToWidgetTemplateProperty(layoutItem, layoutPropertyName, additionalData["layoutData"]?.ToString());

	return this;
}

Item GetWidgetTemplateProperty(string propName)
{
	Item rels = this.getRelationships(widgetTemplatePropTypeName);
	int count = rels.getItemCount();
	for (int i = 0; i < count; ++i)
	{
		Item rel = rels.getItemByIndex(i);
		if (string.Equals(rel.getProperty("name"), propName, StringComparison.OrdinalIgnoreCase))
		{
			return rel;
		}
	}

	return null;
}

bool IsFavoriteSearchItemBeingDeleted()
{
	Item rels = this.getRelationships(widgetTemplatePropTypeName);
	int count = rels.getItemCount();
	if (count == 0)
	{
		return false;
	}

	List<string> idlist = new List<string>();
	for (int i = 0; i < count; ++i)
	{
		Item rel = rels.getItemByIndex(i);
		if (string.Equals(rel.getAction(), "delete", StringComparison.OrdinalIgnoreCase))
		{
			idlist.Add(rel.getID());
		}
	}

	if(idlist.Count == 0)
	{
		return false;
	}

	Item item = this.newItem(widgetTemplatePropTypeName, "get");
	item.setAttribute("idlist", string.Join(",", idlist.ToArray()));
	item.setAttribute("select", "name");
	Item res = item.apply();
	count = res.getItemCount();
	for (int i = 0; i < count; ++i)
	{
		Item rel = res.getItemByIndex(i);
		if (string.Equals(rel.getProperty("name"), favoriteSearchPropertyName, StringComparison.OrdinalIgnoreCase))
		{
			return true;
		}
	}

	return false;
}

void DeleteWidgetTemplatePropertyItem(Item propertyItem, string propertyName)
{
	if (propertyItem == null)
	{
		Item rel = this.newItem(widgetTemplatePropTypeName, "delete");
		rel.setAttribute("where", $"[{tableName}].name='{propertyName}' AND [{tableName}].source_id='{this.getID()}'");
		this.addRelationship(rel);
	}
	else
	{
		if (string.Equals(propertyItem.getAction(), "add", StringComparison.OrdinalIgnoreCase))
		{
			this.removeRelationship(propertyItem);
		}
		else
		{
			propertyItem.setAction("delete");
		}
	}
}

Newtonsoft.Json.Linq.JToken GetFavoriteAdditionalData(string favoriteSearchId)
{
	Item favorite = this.newItem("Favorite", "get");
	favorite.setID(favoriteSearchId);
	favorite = favorite.apply();
	if (favorite.isError())
	{
		return null;
	}

	Item serializedFavoriteItem = favorite.apply("Fav_FavoriteItemJsonBuilder");
	if (serializedFavoriteItem.isError())
	{
		return null;
	}

	try
	{
		Newtonsoft.Json.Linq.JObject parsedItem = Newtonsoft.Json.Linq.JObject.Parse(serializedFavoriteItem.getResult());
		return parsedItem["additional_data"];
	}
	catch (Newtonsoft.Json.JsonReaderException)
	{
		return null;
	}
}

void SetFavoriteDataToWidgetTemplateProperty(Item widgetTemplatePropertyItem, string widgetTemplatePropertyName, string favoritePropertyValue)
{
	if (string.IsNullOrEmpty(favoritePropertyValue))
	{
		DeleteWidgetTemplatePropertyItem(widgetTemplatePropertyItem, widgetTemplatePropertyName);
		return;
	}

	if (widgetTemplatePropertyItem == null)
	{
		AddWidgetTemplateProperty(widgetTemplatePropertyName, favoritePropertyValue);
	}
	else
	{
		SetWidgetTemplatePropertyItemValue(widgetTemplatePropertyItem, favoritePropertyValue);
	}
}

void AddWidgetTemplateProperty(string propertyName, string propertyValue)
{
	Item rel = this.newItem(widgetTemplatePropTypeName, "merge");
	rel.setAttribute("where", $"[{tableName}].name='{propertyName}' AND [{tableName}].source_id='{this.getID()}'");
	rel.setProperty("name", propertyName);
	SetWidgetTemplatePropertyItemValue(rel, propertyValue);
	this.addRelationship(rel);
}

static void SetWidgetTemplatePropertyItemValue(Item propertyItem, string propertyValue)
{
	propertyItem.setProperty("prop_type", "text");
	propertyItem.setProperty("hidden", "1");
	propertyItem.setProperty("prop_predefined", propertyValue);
